// app/api/trigger-workflow/route.ts
'use server';

import { NextRequest } from 'next/server';
import fs from 'fs';
import path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { LangGraphClient } from '@langgraph/client'; // hypothetical SDK

// 1️⃣ Accept a PDF upload via a server action
export async function POST(req: NextRequest) {
  const data = await req.formData();
  const file = data.get('pdf') as File | null;
  if (!file || file.type !== 'application/pdf')
    return new Response('Invalid file', { status: 400 });

  // 2️⃣ Write the PDF to a temp folder
  const tmpDir = path.join(process.cwd(), 'tmp');
  if (!fs.existsSync(tmpDir)) fs.mkdirSync(tmpDir);
  const fileId = uuidv4();
  const filePath = path.join(tmpDir, `${fileId}.pdf`);
  const buffer = Buffer.from(await file.arrayBuffer());
  fs.writeFileSync(filePath, buffer);

  // 3️⃣ Trigger the LangGraph workflow in the background
  // (LangGraph SDK supports async `run` that returns a job id)
  const client = new LangGraphClient({ apiKey: process.env.LANGGRAPH_KEY! });
  client.run('pdf-processing-workflow', { filePath });

  // 4️⃣ Respond immediately – the job runs asynchronously
  return new Response(JSON.stringify({ jobId: fileId }), {
    headers: { 'Content-Type': 'application/json' },
  });
}
```

