// app/page.tsx
'use client';
import { useState } from 'react';

export default function Page() {
  const [file, setFile] = useState<File | null>(null);
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;
    const form = new FormData();
    form.append('pdf', file);
    await fetch('/api/trigger-workflow', { method: 'POST', body: form });
    alert('Workflow started!');
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="file"
        accept="application/pdf"
        onChange={e => setFile(e.target.files?.[0] ?? null)}
      />
      <button type="submit">Upload PDF</button>
    </form>
  );
}
```

*The server action writes the PDF to a temporary file, then calls the LangGraph client to start a background workflow, returning immediately with a job ID.*

